CREATE OR REPLACE FUNCTION finance_private.invalidate_legacy_integrity_cache()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 delete from finance_private.legacy_integrity_cache_state where tenant_id=case when tg_op='DELETE' then old.tenant_id else new.tenant_id end;
 if tg_op='UPDATE' and old.tenant_id is distinct from new.tenant_id then delete from finance_private.legacy_integrity_cache_state where tenant_id=old.tenant_id;end if;
 return null;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.guard_effective_unloading_cost()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e public.finance_expense_items%rowtype;p public.payables%rowtype;t uuid;version jsonb;ticket finance_private.expense_cost_tickets%rowtype;changed boolean;
begin
 t:=new.tenant_id;
 if tg_table_name='finance_expense_allocations' and tg_op='UPDATE' then
  if (old.tenant_id,old.expense_id) is distinct from (new.tenant_id,new.expense_id) and exists(select 1 from finance_private.expense_cost_amendments a where a.tenant_id=old.tenant_id and a.expense_id=old.expense_id) then raise exception 'finance_unloading_cost_allocation_identity_immutable' using errcode='55000';end if;
 end if;
 if tg_table_name='payables' then
  if tg_op='UPDATE' then select * into e from public.finance_expense_items where tenant_id=old.tenant_id and payable_id=old.id and unloading_id is not null;else select * into e from public.finance_expense_items where tenant_id=t and payable_id=new.id and unloading_id is not null;end if;
  if e.id is null then return new;end if;
 else
  if tg_table_name='payables_payments' then select * into p from public.payables where tenant_id=t and id=new.payable_id;select * into e from public.finance_expense_items where tenant_id=t and id=p.source_id and p.source_table='finance_expense_items' and unloading_id is not null;
  else select * into e from public.finance_expense_items where tenant_id=t and id=new.expense_id and unloading_id is not null;end if;
  if e.id is null then return new;end if;
 end if;
 if not pg_try_advisory_xact_lock(hashtextextended(e.tenant_id::text||':finance',0)) then raise exception 'finance_dependency_busy' using errcode='40001';end if;
 if tg_table_name='payables' and tg_op='UPDATE' then
  changed:=new.tenant_id is distinct from old.tenant_id or new.id is distinct from old.id or new.amount is distinct from old.amount or new.source_id is distinct from old.source_id or new.source_table is distinct from old.source_table or new.supplier_id is distinct from old.supplier_id or new.supplier_name is distinct from old.supplier_name or new.driver_id is distinct from old.driver_id;
  if changed then
   delete from finance_private.expense_cost_tickets where transaction_id=txid_current() and tenant_id=old.tenant_id and payable_id=old.id and actor_id=auth.uid() and before_data=to_jsonb(old) and after_data=to_jsonb(new) returning * into ticket;
   if not found or not finance_private.can_repair_unloading(old.tenant_id) or (ticket.before_data-array['amount','status','updated_at']) is distinct from (ticket.after_data-array['amount','status','updated_at']) or new.status<>'pending' then raise exception 'finance_unloading_cost_ticket_required' using errcode='55000';end if;return new;
  end if;
 end if;
 -- Unamended costs retain the original allocation/complement contract. A
 -- payable may represent only the unallocated remainder of the expense.
 if not exists(select 1 from finance_private.expense_cost_amendments a where a.tenant_id=e.tenant_id and a.expense_id=e.id) then return new;end if;
 version:=finance_private.expense_cost_effective(e.tenant_id,e.id);
 if version->>'verified' is distinct from 'true' then raise exception 'finance_expense_cost_unverified' using errcode='55000';end if;
 if tg_table_name='payables' then
  if finance_private.unloading_repair_cents(to_jsonb(new)->'amount') is distinct from version->>'effective_amount_cents' then raise exception 'finance_unloading_cost_payable_mismatch' using errcode='55000';end if;
 elsif tg_table_name='payables_payments' then
  select * into p from public.payables where tenant_id=t and id=new.payable_id;
  if finance_private.unloading_repair_cents(to_jsonb(p)->'amount') is distinct from version->>'effective_amount_cents' then raise exception 'finance_unloading_cost_payable_mismatch' using errcode='55000';end if;
 else
  -- A corrected cost already has one full nominal payable. A later direct
  -- allocation would duplicate its obligation and needs a coordinated writer.
  raise exception 'finance_unloading_cost_allocation_requires_command' using errcode='55000';
 end if;return new;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.capture_payment_cost_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payables%rowtype;cost jsonb;begin
 if new.action is distinct from 'payable_movement_applied' then return new;end if;
 select x.* into p from public.payables_payments pp join public.payables x on x.tenant_id=pp.tenant_id and x.id=pp.payable_id where pp.tenant_id=new.tenant_id and pp.id=new.entity_id;
 if p.source_table='finance_expense_items' then
  cost:=finance_private.expense_cost_version(new.tenant_id,p.source_id);
  if cost->'verified' is distinct from 'true'::jsonb then raise exception 'finance_cost_version_unverified' using errcode='55000';end if;
  new.after_data:=new.after_data||jsonb_build_object('expense_cost_version',cost);
 end if;return new;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.assert_closed_source_mutable(_tenant uuid, _table text, _row jsonb, _depth integer DEFAULT 0)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account uuid;start_date date;end_date date;ref record;source_table text;source jsonb;identifier uuid;raw_date text;hit boolean:=false;outgoing public.finance_movements%rowtype;incoming public.finance_movements%rowtype;native jsonb;imp public.finance_statement_imports%rowtype;registered public.bank_accounts%rowtype;closed public.finance_account_period_closures%rowtype;anchor date;
begin
 if _row is null or _row='null'::jsonb then return;end if;
 if _table='employee_advances' and _row->>'status' is distinct from 'paid' and _row->>'paid_at' is null then return;end if;
 if _depth>8 then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
 if not finance_private.closed_interval_exists(_tenant,null,null,null) then return;end if;
 identifier:=nullif(_row->>'id','')::uuid;
 if exists(select 1 from public.finance_account_period_dependencies d join public.finance_account_period_closures c on c.tenant_id=d.tenant_id and c.id=d.closure_id where d.tenant_id=_tenant and d.source_kind=_table and d.source_id=identifier and d.dependency_role<>'composition_snapshot' and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
 account:=coalesce(nullif(_row->>'bank_account_id','')::uuid,nullif(_row->>'account_id','')::uuid);
 if account is not null and not exists(select 1 from public.bank_accounts a where a.tenant_id=_tenant and a.id=account) then account:=null;end if; if _table='finance_internal_transfers' then
  select * into outgoing from public.finance_movements where tenant_id=_tenant and id=(_row->>'outgoing_id')::uuid;
  select * into incoming from public.finance_movements where tenant_id=_tenant and id=(_row->>'incoming_id')::uuid;
  -- An already identified departure may arrive later. Its frozen leg stays intact.
  if finance_private.closed_interval_exists(_tenant,outgoing.bank_account_id,outgoing.occurred_on,outgoing.occurred_on) then
   if not exists(select 1 from public.finance_transfer_departures p where p.tenant_id=_tenant and p.outgoing_id=outgoing.id and p.destination_account_id=incoming.bank_account_id
    and not exists(select 1 from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=outgoing.bank_account_id and outgoing.occurred_on between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)
      and (incoming.occurred_on<=c.period_end or not exists(select 1 from public.finance_account_period_dependencies d where d.tenant_id=_tenant and d.closure_id=c.id and d.source_kind='finance_transfer_departures' and d.source_id=p.id)))) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',to_jsonb(incoming),_depth+1);return;
  end if;
 end if;
 if _table='finance_statement_verifications' then
  select * into imp from public.finance_statement_imports where tenant_id=_tenant and id=(_row->>'import_id')::uuid;
  native:=_row#>'{report,native_evidence}';
  if native is not null then
   if finance_private.closed_interval_exists(_tenant,imp.bank_account_id,(native#>>'{period,start,date}')::date,(native#>>'{period,end,date}')::date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   anchor:=(native#>>'{ledger_balance,as_of,date}')::date;
   for closed in select c.* from public.finance_account_period_closures c where c.tenant_id=_tenant and c.account_id=imp.bank_account_id and anchor between c.period_start and c.period_end and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id) loop
    select * into registered from public.bank_accounts where tenant_id=_tenant and id=imp.bank_account_id;
    if anchor is distinct from closed.period_end or native#>>'{ledger_balance,amount_cents}' is distinct from closed.snapshot#>>'{balances,closing_cents}'
     or native#>>'{ledger_balance,as_of,offset_minutes}' is distinct from '-180' or native#>>'{period,start,offset_minutes}' is distinct from '-180' or native#>>'{period,end,offset_minutes}' is distinct from '-180'
     or native->>'currency' is distinct from 'BRL' or native->>'parser_version' is distinct from 'native-ofx-v1'
     or native#>>'{account,bank_id}' is distinct from btrim(registered.bank_code) or native#>>'{account,branch_id}' is distinct from btrim(registered.branch_number) or native#>>'{account,account_id}' is distinct from btrim(registered.account_number)
     or native#>>'{account,account_type}' is distinct from (case registered.account_type when 'checking' then 'CHECKING' when 'savings' then 'SAVINGS' end)
     or _row->>'outcome' is distinct from 'rows_match' or _row#>>'{report,hash_verified}' is distinct from 'true' or _row#>>'{report,actual_hash}' is distinct from imp.file_hash or _row#>>'{report,identity_trust}' is distinct from 'native_file_identifier'
     or native->>'outside_declared_period' is distinct from 'false' or native->'repeated_bank_ids' is distinct from '[]'::jsonb
    then raise exception 'finance_closed_anchor_conflict' using errcode='55000';end if;
   end loop;
  end if;
 end if;
 if _table in('finance_statement_imports','finance_statement_coverage_approvals','finance_period_evidence_reviews','finance_legacy_cut_reviews') then
  start_date:=(_row->>'period_start')::date;end_date:=(_row->>'period_end')::date;
 elsif _table='finance_account_openings' then start_date:=(_row->>'effective_from')::date;end_date:=null;
 else
  raw_date:=coalesce(_row->>'occurred_on',_row->>'posted_on',_row->>'posted_at',_row->>'received_at',_row->>'paid_at',_row->>'effective_at',_row->>'payment_date',_row->>'advance_date',_row->>'occurred_at',_row->>'competence_date');
  if raw_date is not null then start_date:=(raw_date::timestamptz at time zone 'America/Sao_Paulo')::date;
   if raw_date ~ '^\d{4}-\d{2}-\d{2}$' then start_date:=raw_date::date;end if;end_date:=start_date;end if;
 end if;
 if start_date is not null or _table in('finance_movements','finance_bank_entries','bank_transactions','receivables_payments','payables_payments','driver_settlement_payments','closing_report_payments','load_payments','employee_advances','payroll_entry_items') then
  if finance_private.closed_interval_exists(_tenant,account,start_date,end_date) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
  hit:=true;
 end if;
 for ref in select key,value from jsonb_each_text(_row) where key in('import_id','first_import_id','row_id','review_id','group_id','opening_id','approval_id','bank_transaction_id','bank_entry_id','movement_id','outgoing_id','incoming_id','receivable_payment_id','payment_id') and value is not null loop
  source_table:=case ref.key when 'import_id' then case when _table='bank_transactions' then null else 'finance_statement_imports' end when 'first_import_id' then 'finance_statement_imports' when 'row_id' then 'finance_statement_rows' when 'review_id' then 'finance_statement_identity_reviews' when 'group_id' then 'finance_reconciliation_groups' when 'opening_id' then 'finance_account_openings' when 'approval_id' then 'finance_statement_coverage_approvals' when 'bank_transaction_id' then 'bank_transactions' when 'bank_entry_id' then 'finance_bank_entries' when 'movement_id' then 'finance_movements' when 'outgoing_id' then 'finance_movements' when 'incoming_id' then 'finance_movements' when 'receivable_payment_id' then 'receivables_payments' when 'payment_id' then case when _table='receivable_payment_reversals' then 'receivables_payments' end end;
  if source_table is not null then
   if _table='receivable_payment_reversals' and ref.key='payment_id' and start_date is not null then continue;end if;
   execute format('select to_jsonb(s) from public.%I s where s.tenant_id=$1 and s.id=$2',source_table) into source using _tenant,ref.value::uuid;
   if source is null then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
   perform finance_private.assert_closed_source_mutable(_tenant,source_table,source,_depth+1);hit:=true;
  end if;
 end loop;
 if _table='finance_reconciliation_groups' then
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'movement_ids') loop select to_jsonb(m) into source from public.finance_movements m where m.tenant_id=_tenant and m.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_movements',source,_depth+1);end loop;
  for identifier in select value::uuid from jsonb_array_elements_text(_row->'bank_entry_ids') loop select to_jsonb(e) into source from public.finance_bank_entries e where e.tenant_id=_tenant and e.id=identifier;perform finance_private.assert_closed_source_mutable(_tenant,'finance_bank_entries',source,_depth+1);end loop;hit:=true;
 end if;
 if not hit then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.payable_effective_cost_evidence(t uuid, payable uuid, ev jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$

declare p public.payables%rowtype;cost jsonb;versions jsonb;coverage jsonb;begin

 select * into p from public.payables where tenant_id=t and id=payable;

 if p.source_table is distinct from 'finance_expense_items' then return ev;end if;

 if not exists(select 1 from public.finance_expense_items e where e.tenant_id=t and e.id=p.source_id and e.payable_id=p.id) then

  return ev||jsonb_build_object('valid',false,'nominal_cents',null,'paid_cents',null,'open_cents',null,'expense_cost_version',null,'payment_cost_versions','[]'::jsonb,'issues',coalesce(ev->'issues','[]')||jsonb_build_array('finance_cost_version_unverified'),'revision',md5(jsonb_build_object('prior',ev->'revision','missing_cost_source',p.source_id)::text));

 end if;

 cost:=finance_private.expense_cost_version(t,p.source_id);coverage:=finance_private.expense_cost_coverage(t,p.source_id);

 select coalesce(jsonb_agg(jsonb_build_object('payment_id',e.entity_id,'event_id',e.id,'cost_version',e.after_data->'expense_cost_version') order by e.id),'[]') into versions

 from public.finance_events e join public.payables_payments pp on pp.tenant_id=e.tenant_id and pp.id=e.entity_id

 where e.tenant_id=t and pp.payable_id=payable and e.action='payable_movement_applied' and e.after_data ? 'expense_cost_version';

 ev:=ev||jsonb_build_object('coverage',coverage,'expense_cost_version',cost,'payment_cost_versions',versions,'revision',md5(jsonb_build_object('prior',ev->'revision','cost',cost,'coverage',coverage,'payments',versions)::text));

 if cost->'verified' is distinct from 'true'::jsonb or coverage->'verified' is distinct from 'true'::jsonb then ev:=ev||jsonb_build_object('valid',false,'nominal_cents',null,'paid_cents',null,'open_cents',null,'issues',coalesce(ev->'issues','[]')||jsonb_build_array('finance_cost_version_unverified'));end if;

 return ev;

end$function$
;

CREATE OR REPLACE FUNCTION finance_private.guard_payable_revision_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare protected boolean;ticket finance_private.payable_approval_tickets%rowtype;
begin
 if new.status is distinct from 'approved' or old.status='approved' then return new;end if;
 protected:=exists(select 1 from public.finance_expense_items e join finance_private.expense_open_complement_amendments a on a.tenant_id=e.tenant_id and a.expense_id=e.id where e.tenant_id=old.tenant_id and e.payable_id=old.id);
 if not protected and not exists(select 1 from finance_private.payable_approval_tickets t where t.transaction_id=txid_current() and t.tenant_id=old.tenant_id and t.payable_id=old.id) then return new;end if;
 if not pg_try_advisory_xact_lock(hashtextextended(old.tenant_id::text||':finance',0)) then raise exception 'finance_payable_approval_busy' using errcode='40001';end if;
 delete from finance_private.payable_approval_tickets t where t.transaction_id=txid_current() and t.tenant_id=old.tenant_id and t.payable_id=old.id and t.actor_id=auth.uid() and t.before_data=to_jsonb(old) and t.after_data=to_jsonb(new) returning * into ticket;
 if ticket.request_id is null or not finance_private.can_access(old.tenant_id) or (ticket.before_data-array['status','approved_at','approved_by','updated_at']) is distinct from (ticket.after_data-array['status','approved_at','approved_by','updated_at']) or new.approved_by is distinct from auth.uid() or new.approved_at is null then raise exception 'finance_payable_approval_revision_required' using errcode='55000';end if;
 return new;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.record_movement(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 t uuid; actor uuid:=auth.uid(); request uuid; existing public.finance_commands%rowtype;
 movement uuid; account uuid; driver uuid; cents bigint; result jsonb; actor_name text;
begin
 if jsonb_typeof(_payload) is distinct from 'object' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 t:=(_payload->>'tenant_id')::uuid; request:=(_payload->>'request_id')::uuid;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501'; end if;
 if request is null or _payload->>'version' is distinct from '1'
 or exists(select 1 from jsonb_object_keys(_payload) k where k not in
 ('version','tenant_id','request_id','bank_account_id','direction','nature','amount_cents','occurred_on',
  'description','beneficiary_name','beneficiary_document','driver_id','bank_reference','receipt_path','reason')) then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 -- Serializes retries and reference checks, including requests with different IDs.
 perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into existing from public.finance_commands where tenant_id=t and request_id=request;
 if found then
  if existing.actor_id<>actor or existing.action<>'record_movement' or existing.payload<>_payload then
   raise exception 'finance_request_conflict' using errcode='23505'; end if;
  return existing.result;
 end if;
 if _payload->>'nature'='transfer' then raise exception 'finance_transfer_pair_required' using errcode='22023';end if;
 if coalesce(_payload->>'amount_cents','') !~ '^[0-9]{1,14}$'
 or length(btrim(coalesce(_payload->>'reason',''))) not between 5 and 2000
 or coalesce(_payload->>'occurred_on','') !~ '^\d{4}-\d{2}-\d{2}$' then
  raise exception 'finance_invalid_payload' using errcode='22023'; end if;
 cents:=(_payload->>'amount_cents')::bigint;
 if cents<=0 or (_payload->>'occurred_on')::date>(clock_timestamp() at time zone 'America/Sao_Paulo')::date then
  raise exception 'finance_invalid_realized_movement' using errcode='22023'; end if;
 account:=(_payload->>'bank_account_id')::uuid; driver:=nullif(_payload->>'driver_id','')::uuid;
 perform 1 from public.bank_accounts where id=account and tenant_id=t and active for share;
 if not found then raise exception 'finance_invalid_account' using errcode='22023'; end if;
 if driver is not null then
  perform 1 from public.drivers where id=driver and tenant_id=t and active for share;
  if not found then raise exception 'finance_invalid_driver' using errcode='22023'; end if;
 end if;
 if _payload->>'nature'='driver_advance' and (driver is null or _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_driver_advance' using errcode='22023'; end if;
 if (_payload->>'nature' in ('receipt','customer_advance') and _payload->>'direction' is distinct from 'in')
 or (_payload->>'nature'='payment' and _payload->>'direction' is distinct from 'out') then
  raise exception 'finance_invalid_direction' using errcode='22023';end if;
 if nullif(btrim(_payload->>'receipt_path'),'') is not null and
  ((_payload->>'receipt_path') not like t::text||'/%' or (_payload->>'receipt_path') like '%..%') then
  raise exception 'finance_invalid_receipt_scope' using errcode='22023'; end if;
 if nullif(btrim(_payload->>'bank_reference'),'') is not null and exists(
  select 1 from finance_private.active_movements where tenant_id=t and bank_account_id=account
   and bank_reference=btrim(_payload->>'bank_reference')) then
  raise exception 'finance_reference_already_recorded' using errcode='23505'; end if;
 insert into public.finance_movements(tenant_id,bank_account_id,direction,nature,amount_cents,occurred_on,
  description,beneficiary_name,beneficiary_document,driver_id,bank_reference,receipt_path,created_by)
 values(t,account,_payload->>'direction',_payload->>'nature',cents,(_payload->>'occurred_on')::date,
  btrim(_payload->>'description'),btrim(_payload->>'beneficiary_name'),nullif(btrim(_payload->>'beneficiary_document'),''),
  driver,nullif(btrim(_payload->>'bank_reference'),''),nullif(btrim(_payload->>'receipt_path'),''),actor)
 returning id into movement;
 select coalesce(u.raw_user_meta_data->>'full_name',u.email,actor::text) into actor_name from auth.users u where u.id=actor;
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data)
 select t,'movement',movement,'recorded',actor,coalesce(actor_name,actor::text),btrim(_payload->>'reason'),to_jsonb(m)
 from public.finance_movements m where m.id=movement;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'movement_id',movement,'confirmed',true);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result)
 values(t,request,actor,'record_movement',_payload,result);
 return result;
end;
$function$
;

CREATE OR REPLACE FUNCTION finance_private.guard_late_payment_composition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare current_row jsonb;actor_name text;begin
 if not pg_try_advisory_xact_lock(hashtextextended(new.tenant_id::text||':finance',0)) then raise exception 'finance_period_source_busy' using errcode='40001';end if;
 execute format('select to_jsonb(p) from public.%I p where p.tenant_id=$1 and p.id=$2',tg_table_name) into current_row using new.tenant_id,new.id;
 if current_row is null then return new;end if;
 if finance_private.closed_interval_exists(new.tenant_id,null,null,null) and finance_private.late_payment_composition_proved(new.tenant_id,tg_table_name,current_row) then
  if not finance_private.can_access(new.tenant_id) then raise exception 'finance_access_denied' using errcode='42501';end if;
  select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,auth.uid()::text) into actor_name from auth.users where id=auth.uid();
  insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,after_data) values(new.tenant_id,'late_period_composition',new.id,'closed_period_composition_recorded',auth.uid(),coalesce(actor_name,auth.uid()::text),'Detalhamento posterior vinculado a dinheiro já congelado',jsonb_build_object('source_table',tg_table_name,'source_id',new.id,'cash_changed',false,'source',current_row));
  return new;
 end if;
 perform finance_private.assert_closed_source_mutable(new.tenant_id,tg_table_name,current_row);return new;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.verify_receipt_object()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare evidence jsonb;
begin
 if new.receipt_path is null then return new;end if;
 if new.receipt_path not like new.tenant_id::text||'/%' or new.receipt_path like '%..%' then
   raise exception 'finance_invalid_receipt_scope' using errcode='22023';end if;
 select to_jsonb(o) into evidence from storage.objects o where bucket_id='receipts' and name=new.receipt_path for share nowait;
 if evidence is null then raise exception 'finance_receipt_not_found' using errcode='22023';end if;
 if coalesce(evidence#>>'{metadata,mimetype}','') not in('application/pdf','image/jpeg','image/png','image/webp')
   or coalesce(evidence#>>'{metadata,size}','') !~ '^[1-9][0-9]{0,7}$' then
   raise exception 'finance_invalid_receipt_metadata' using errcode='22023';end if;
 new.receipt_evidence:=jsonb_build_object('object_id',evidence->>'id','bucket','receipts','path',new.receipt_path,
   'metadata',evidence->'metadata','created_at',evidence->>'created_at','verified_at',clock_timestamp());
 return new;
end;$function$
;

CREATE OR REPLACE FUNCTION finance_private.guard_closed_financial_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare data jsonb;t uuid;identity jsonb;bank public.bank_accounts%rowtype;begin
 if tg_op='UPDATE' and to_jsonb(new)=to_jsonb(old) then return new;end if;
 for data in select value from jsonb_array_elements(case when tg_op='INSERT' then jsonb_build_array(to_jsonb(new)) when tg_op='DELETE' then jsonb_build_array(to_jsonb(old)) else jsonb_build_array(to_jsonb(old),to_jsonb(new)) end) loop
  t:=(data->>'tenant_id')::uuid;
  if t is null then raise exception 'finance_closed_source_resolution_required' using errcode='55000';end if;
  if not pg_try_advisory_xact_lock(hashtextextended(t::text||':finance',0)) then raise exception 'finance_period_source_busy' using errcode='40001';end if;
  if not finance_private.closed_interval_exists(t,null,null,null) then continue;end if;
 if tg_op='INSERT' then
  if tg_table_name='employee_advances' then if new.status='paid' then continue;end if;
  elsif tg_table_name='payroll_entry_items' then if new.nature='already_paid' then continue;end if;end if;
 end if;
 if tg_op='UPDATE' and tg_table_name='employee_advances' then
  if old.status is distinct from 'paid' and new.status='paid' and to_jsonb(old)-array['status','paid_by','paid_at','updated_by','updated_at'] is not distinct from to_jsonb(new)-array['status','paid_by','paid_at','updated_by','updated_at'] then continue;end if;
 end if;
  if tg_op='INSERT' and tg_table_name in('payables_payments','receivables_payments','driver_settlement_payments','bank_transactions','load_payments','closing_report_payments') then continue;end if;
  if tg_table_name='bank_accounts' then
   if tg_op='UPDATE' and (to_jsonb(old)-array['name','bank_name','pix_key','updated_at'])=(to_jsonb(new)-array['name','bank_name','pix_key','updated_at']) then continue;end if;
   if exists(select 1 from public.finance_account_period_closures c where c.tenant_id=t and c.account_id=(data->>'id')::uuid and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_account_period_closed' using errcode='55000';end if;
   if exists(select 1 from public.bank_accounts b join public.finance_account_period_closures c on c.tenant_id=b.tenant_id and c.account_id=b.id where b.tenant_id=t and b.account_type is distinct from 'cash' and data->>'account_type' is distinct from 'cash' and b.id<>(data->>'id')::uuid and regexp_replace(coalesce(b.bank_code,''),'\D','','g')=regexp_replace(coalesce(data->>'bank_code',''),'\D','','g') and regexp_replace(coalesce(b.branch_number,''),'\D','','g')=regexp_replace(coalesce(data->>'branch_number',''),'\D','','g') and regexp_replace(coalesce(b.account_number,''),'\D','','g')=regexp_replace(coalesce(data->>'account_number',''),'\D','','g') and not exists(select 1 from public.finance_account_period_reopenings r where r.tenant_id=c.tenant_id and r.closure_id=c.id)) then raise exception 'finance_closed_account_identity_conflict' using errcode='55000';end if;
  elsif tg_table_name='payroll_entry_items' and data->>'nature' is distinct from 'already_paid' then continue;
  else perform finance_private.assert_closed_source_mutable(t,tg_table_name,data);end if;
 end loop;
 if tg_op='DELETE' then return old;end if;return new;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.payable_portfolio(_tenant uuid, _filters jsonb, _page integer, _revision text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$

declare basis text;starts date;ends date;supplier uuid;filter_category text;filter_search text;filter_status text;filter_source text;today date:=(statement_timestamp() at time zone 'America/Sao_Paulo')::date;result jsonb;

begin

 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;

 if jsonb_typeof(_filters) is distinct from 'object' or _page is null or _page not between 1 and 1000000 or exists(select 1 from jsonb_each(_filters) f where f.key<>all(array['date_basis','from','to','category','supplier_id','search','status','source']) or jsonb_typeof(f.value) not in('string','null')) then raise exception 'finance_invalid_filters' using errcode='22023';end if;

 if exists(select 1 from jsonb_each_text(_filters) f where f.key in('from','to') and f.value is not null and f.value !~ '^\d{4}-\d{2}-\d{2}$') then raise exception 'finance_invalid_filters' using errcode='22023';end if;

 basis:=coalesce(_filters->>'date_basis','due_date');starts:=nullif(_filters->>'from','')::date;ends:=nullif(_filters->>'to','')::date;supplier:=nullif(_filters->>'supplier_id','')::uuid;filter_category:=nullif(btrim(_filters->>'category'),'');

 filter_search:=nullif(btrim(_filters->>'search'),'');filter_status:=nullif(_filters->>'status','');filter_source:=nullif(_filters->>'source','');

 if length(filter_search)>200 or filter_status<>all(array['pending','approved','partial','paid','overdue','cancelled','unknown']) or filter_source<>all(array['manual','system','unknown']) then raise exception 'finance_invalid_filters' using errcode='22023';end if;

 if basis<>all(array['due_date','created_at']) or starts>ends or (starts is not null and not isfinite(starts)) or (ends is not null and not isfinite(ends)) or length(filter_category)>100 or (_revision is not null and _revision !~ '^[a-f0-9]{32}$') then raise exception 'finance_invalid_filters' using errcode='22023';end if;

 with selected as materialized(

 select p.*,case when basis='due_date' then case when isfinite(p.due_date) then p.due_date end else case when isfinite(p.created_at) then (p.created_at at time zone 'America/Sao_Paulo')::date end end filter_day

 from public.payables p where p.tenant_id=_tenant and (supplier is null or p.supplier_id=supplier) and (filter_category is null or p.category=filter_category)

 and (filter_search is null or strpos(lower(concat_ws(' ',p.supplier_name,p.description,p.document_number)),lower(filter_search))>0)

 and (filter_source is null or (filter_source='unknown' and coalesce(p.source,'system')<>all(array['manual','system'])) or coalesce(p.source,'system')=filter_source)

 and (filter_status is null or (filter_status='overdue' and isfinite(p.due_date) and p.due_date<today and coalesce(p.status,'unknown')<>all(array['paid','cancelled'])) or (filter_status='unknown' and (p.status is null or p.status<>all(array['pending','approved','partial','paid','overdue','cancelled']))) or (filter_status<>'overdue' and p.status=filter_status))

 ), scoped as materialized(select * from selected where filter_day is null or ((starts is null or filter_day>=starts) and (ends is null or filter_day<=ends))),

 evidence as materialized(select p.*,finance_private.payable_effective_cost_evidence(_tenant,p.id,finance_private.payable_portfolio_evidence(_tenant,p.id)) ev from scoped p),

 rows as materialized(select id,coalesce(status,'unknown') status,filter_day,

 jsonb_build_object('source_table','payables','source_id',id,'status',coalesce(status,'unknown'),'supplier_id',supplier_id,'supplier_name',supplier_name,'category',category,'description',description,

 'due_on',case when isfinite(due_date) then due_date end,'created_on',case when isfinite(created_at) then (created_at at time zone 'America/Sao_Paulo')::date end,

 'date_in_range',filter_day is not null,'origin',jsonb_build_object('source_table',source_table,'source_id',source_id),'declared_amount',amount::text,'declared_paid',paid_amount::text,

 'coverage',ev->'coverage','expense_cost_version',ev->'expense_cost_version','payment_cost_versions',coalesce(ev->'payment_cost_versions','[]'::jsonb),'payment_ids',ev->'payment_ids','valid',ev->'valid','issues',ev->'issues','nominal_cents',ev->'nominal_cents','paid_cents',ev->'paid_cents','open_cents',ev->'open_cents','source_revision',ev->'revision') value,

 (ev->>'valid')::boolean valid,(ev->>'nominal_cents')::numeric nominal,(ev->>'paid_cents')::numeric paid,(ev->>'open_cents')::numeric remaining,

 case when isfinite(due_date) then due_date end due_on from evidence),

 summary as(select count(*) total,count(*) filter(where status='cancelled') cancelled,count(*) filter(where not valid) invalid,count(*) filter(where filter_day is null) undated,

 coalesce(sum(nominal),0) nominal,coalesce(sum(paid),0) paid,coalesce(sum(remaining),0) remaining,coalesce(sum(remaining) filter(where due_on<today),0) overdue from rows),

 fingerprint as(select md5(jsonb_build_object('tenant',_tenant,'filters',jsonb_build_object('date_basis',basis,'from',starts,'to',ends,'category',filter_category,'supplier_id',supplier,'search',filter_search,'status_filter',filter_status,'source_filter',filter_source),'day',today,'sources',coalesce(jsonb_agg(value order by id),'[]'))::text) revision from rows),

 paged as(select value,filter_day,id from rows order by filter_day nulls last,id limit 30 offset (_page-1)*30),

 grouped as(select status,count(*) count from rows group by status),issues as(select issue,count(*) count from rows cross join lateral jsonb_array_elements_text(value->'issues')issue group by issue)

 select jsonb_build_object('version',1,'tenant_id',_tenant,'basis','current_operational','date_basis',basis,'from',starts,'to',ends,'category',filter_category,'supplier_id',supplier,'search',filter_search,'status_filter',filter_status,'source_filter',filter_source,'as_of',today,

 'revision',f.revision,'page',_page,'page_size',30,'total_titles',s.total,'cancelled_titles',s.cancelled,'invalid_titles',s.invalid,'undated_titles',s.undated,'totals_valid',s.invalid=0,

 'nominal_cents',case when s.invalid=0 then s.nominal::text end,'paid_cents',case when s.invalid=0 then s.paid::text end,'open_cents',case when s.invalid=0 then s.remaining::text end,'overdue_cents',case when s.invalid=0 then s.overdue::text end,

 'status_counts',coalesce((select jsonb_agg(to_jsonb(g) order by status) from grouped g),'[]'),'issue_counts',coalesce((select jsonb_agg(to_jsonb(g) order by issue) from issues g),'[]'),

 'rows',coalesce((select jsonb_agg(value order by filter_day nulls last,id) from paged),'[]')) into result from summary s cross join fingerprint f;

 if _revision is not null and result->>'revision'<>_revision then raise exception 'finance_payable_portfolio_changed' using errcode='40001';end if;

 return result;

end$function$
;

CREATE OR REPLACE FUNCTION finance_private.manual_expense_cancellation_context(_tenant uuid, _payable uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payables%rowtype;cmd public.finance_commands%rowtype;cancel public.finance_manual_expense_cancellations%rowtype;snapshot jsonb;issue text;cents numeric;begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into p from public.payables where tenant_id=_tenant and id=_payable;
 select * into cmd from public.finance_commands where tenant_id=_tenant and action='record_manual_expense' and result->>'payable_id'=_payable::text order by request_id limit 1;
 select * into cancel from public.finance_manual_expense_cancellations where tenant_id=_tenant and payable_id=_payable;
 snapshot:=jsonb_build_object('payable',to_jsonb(p),'command',to_jsonb(cmd),'supplier',(select to_jsonb(s) from public.clients s where s.tenant_id=_tenant and s.id=p.supplier_id),
 'commands',(select coalesce(jsonb_agg(to_jsonb(c) order by c.request_id),'[]') from public.finance_commands c where c.tenant_id=_tenant and c.action='record_manual_expense' and c.result->>'payable_id'=_payable::text),
 'payments',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.payables_payments x where x.tenant_id=_tenant and x.payable_id=_payable),
 'links',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_payable_movement_links x where x.tenant_id=_tenant and x.payable_id=_payable),
 'evidence',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_manual_expense_evidence x where x.tenant_id=_tenant and x.payable_id=_payable),
 'expense_items',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.finance_expense_items x where x.tenant_id=_tenant and x.payable_id=_payable),
 'advances',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.employee_advances x where x.tenant_id=_tenant and x.payable_id=_payable),
 'payroll_items',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.payroll_entry_items x where x.tenant_id=_tenant and x.source_table in('payables','manual_expense','finance_commands') and x.source_id in(_payable,cmd.request_id)),
 'settlement_items',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.driver_settlement_items x where x.tenant_id=_tenant and x.source_table in('payables','manual_expense','finance_commands') and x.source_id in(_payable,cmd.request_id)),
 'obligations',(select coalesce(jsonb_agg(to_jsonb(x) order by x.id),'[]') from public.financial_obligations x where x.tenant_id=_tenant and x.source_table in('payables','manual_expense','finance_commands') and x.source_id in(_payable,cmd.request_id)),
 'closure_dependencies',(select coalesce(jsonb_agg(to_jsonb(x) order by x.closure_id,x.source_kind,x.source_id),'[]') from public.finance_account_period_dependencies x where x.tenant_id=_tenant and (x.source_kind='payables' and x.source_id=_payable or x.source_kind in('manual_expense','finance_commands') and x.source_id=cmd.request_id)),
 'cancellation',case when cancel.id is not null then to_jsonb(cancel)-'source_snapshot' end);
 if coalesce(cmd.payload->>'amount_cents','') ~ '^[0-9]{1,14}$' then cents:=(cmd.payload->>'amount_cents')::numeric;end if;
 if p.id is null or cmd.request_id is null then issue:='finance_manual_expense_not_found';
 elsif cancel.id is not null then issue:='finance_manual_expense_already_cancelled';
 elsif jsonb_array_length(snapshot->'commands')<>1 or cents is null or cents<=0 or cents>99999999999999
  or cmd.payload->>'request_id' is distinct from cmd.request_id::text or cmd.result->>'request_id' is distinct from cmd.request_id::text or cmd.payload->'version' is distinct from '1'::jsonb or cmd.result->'confirmed' is distinct from 'true'::jsonb or cmd.payload->>'tenant_id' is distinct from _tenant::text or cmd.result->>'tenant_id' is distinct from _tenant::text
  or p.amount*100 is distinct from cents or p.status not in('pending','approved') or p.paid_amount is distinct from 0::numeric or p.paid_at is not null
  or p.source is distinct from 'manual' or p.source_table is not null or p.source_id is not null or p.driver_id is not null or p.dispatch_trip_id is not null or p.load_id is not null or p.vehicle_id is not null
  or p.supplier_id::text is distinct from nullif(cmd.payload->>'supplier_id','') or p.supplier_name is distinct from btrim(cmd.payload->>'supplier_name')
  or (p.competence_date is not null and not isfinite(p.competence_date)) or (p.due_date is not null and not isfinite(p.due_date)) or p.category is distinct from cmd.payload->>'category' or p.competence_date::text is distinct from nullif(cmd.payload->>'competence_date','') or p.due_date::text is distinct from nullif(cmd.payload->>'due_date','') then issue:='finance_manual_expense_source_inconsistent';
 elsif p.category='unloading' then issue:='finance_manual_expense_unloading_requires_resolution';
 elsif jsonb_array_length(snapshot->'payments')+jsonb_array_length(snapshot->'links')>0 or nullif(cmd.payload->>'movement_id','') is not null or nullif(cmd.result->>'movement_id','') is not null or cmd.result->'allocation' is distinct from 'null'::jsonb then issue:='finance_manual_expense_money_dependency';
 elsif jsonb_array_length(snapshot->'expense_items')+jsonb_array_length(snapshot->'advances')+jsonb_array_length(snapshot->'payroll_items')+jsonb_array_length(snapshot->'settlement_items')+jsonb_array_length(snapshot->'obligations')>0 then issue:='finance_manual_expense_materialization_dependency';
 end if;
 if issue is null then begin perform finance_private.assert_closed_source_mutable(_tenant,'payables',to_jsonb(p));exception when sqlstate '55000' then issue:='finance_manual_expense_closed_period_dependency';end;end if;
 return jsonb_build_object('version',1,'tenant_id',_tenant,'payable_id',_payable,'original_request_id',cmd.request_id,'revision',md5(snapshot::text),'eligible',issue is null,'issue',issue,'snapshot',snapshot,'cancellation',case when cancel.id is not null then to_jsonb(cancel)-'source_snapshot' end,'effects',jsonb_build_object('cost_removed_cents',cents::text,'obligation_cancelled_cents',cents::text,'cash_changed',false));
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.cancel_manual_expense(_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t uuid;request uuid;payable uuid;actor uuid:=auth.uid();actor_name text;context jsonb;prior public.finance_commands%rowtype;p public.payables%rowtype;cancel uuid;result jsonb;begin
 if jsonb_typeof(_payload) is distinct from 'object' or _payload->'version' is distinct from '1'::jsonb or jsonb_typeof(_payload->'reason') is distinct from 'string' or length(btrim(_payload->>'reason')) not between 10 and 2000 or coalesce(_payload->>'revision','') !~ '^[0-9a-f]{32}$' or exists(select 1 from jsonb_object_keys(_payload) k where k not in('version','tenant_id','request_id','payable_id','revision','reason')) then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 t:=(_payload->>'tenant_id')::uuid;request:=(_payload->>'request_id')::uuid;payable:=(_payload->>'payable_id')::uuid;if t is null or request is null or payable is null then raise exception 'finance_invalid_payload' using errcode='22023';end if;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;perform pg_advisory_xact_lock(hashtextextended(t::text||':finance',0));if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 select * into prior from public.finance_commands where tenant_id=t and request_id=request;if found then if prior.actor_id<>actor or prior.action<>'cancel_manual_expense' or prior.payload<>_payload then raise exception 'finance_request_conflict' using errcode='23505';end if;return prior.result;end if;
 perform 1 from public.payroll_periods where tenant_id=t order by id for update;perform 1 from public.payroll_entries where tenant_id=t order by payroll_period_id,id for update;
 select * into p from public.payables where tenant_id=t and id=payable;perform 1 from public.clients where tenant_id=t and id=p.supplier_id for update;select * into p from public.payables where tenant_id=t and id=payable for update;
 if not finance_private.can_access(t) then raise exception 'finance_access_denied' using errcode='42501';end if;
 context:=finance_private.manual_expense_cancellation_context(t,payable);if context->>'revision' is distinct from _payload->>'revision' then raise exception 'finance_manual_expense_cancellation_changed' using errcode='40001';end if;
 if context->'eligible' is distinct from 'true'::jsonb then raise exception '%',context->>'issue' using errcode='23514';end if;
 perform finance_private.assert_closed_source_mutable(t,'payables',to_jsonb(p));perform finance_private.assert_closed_source_mutable(t,'payables',to_jsonb(p)||jsonb_build_object('status','cancelled'));
 select coalesce(nullif(raw_user_meta_data->>'full_name',''),email,actor::text) into actor_name from auth.users where id=actor;actor_name:=coalesce(actor_name,actor::text);
 insert into public.finance_manual_expense_cancellations(tenant_id,payable_id,original_request_id,revision,source_snapshot,actor_id,actor_name,reason,request_id) values(t,payable,(context->>'original_request_id')::uuid,context->>'revision',context->'snapshot',actor,actor_name,btrim(_payload->>'reason'),request) returning id into cancel;
 update public.payables set status='cancelled',updated_at=clock_timestamp() where tenant_id=t and id=payable;
 result:=jsonb_build_object('version',1,'tenant_id',t,'request_id',request,'payable_id',payable,'original_request_id',context->>'original_request_id','cancellation_id',cancel,'amount_cents',context#>>'{effects,cost_removed_cents}','confirmed',true,'cash_changed',false);
 insert into public.finance_events(tenant_id,entity_type,entity_id,action,actor_id,actor_name,reason,before_data,after_data) values(t,'payable',payable,'manual_expense_cancelled',actor,actor_name,btrim(_payload->>'reason'),context->'snapshot',result);
 insert into public.finance_commands(tenant_id,request_id,actor_id,action,payload,result) values(t,request,actor,'cancel_manual_expense',_payload,result);return result;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.guard_cancelled_manual_expense_dependency()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare data jsonb;t uuid;payable uuid;source uuid;begin
 if tg_op='DELETE' then data:=to_jsonb(old);else data:=to_jsonb(new);end if;t:=(data->>'tenant_id')::uuid;
 if not pg_try_advisory_xact_lock(hashtextextended(t::text||':finance',0)) then raise exception 'finance_dependency_busy' using errcode='40001';end if;
 if tg_table_name='payables' then
  if tg_op in('UPDATE','DELETE') and finance_private.manual_expense_is_cancelled(old.tenant_id,old.id) then
   if tg_op='DELETE' then raise exception 'finance_manual_expense_already_cancelled' using errcode='55000';end if;
   if new.status is distinct from 'cancelled' or (to_jsonb(new)-'status'-'updated_at') is distinct from (to_jsonb(old)-'status'-'updated_at') then raise exception 'finance_manual_expense_already_cancelled' using errcode='55000';end if;return new;
  end if;
