  perform id from public.dispatch_trips where id=tid for key share nowait;
  if exists(select 1 from private.dispatch_trip_corrections where trip_id=tid) then
   if tg_table_name='dispatch_trips' then
    if tg_op='DELETE' or (to_jsonb(new)-array['notes','updated_at']) is distinct from (to_jsonb(old)-array['notes','updated_at']) then raise exception 'corrected_trip_history_immutable' using errcode='55000';end if;
   elsif tg_table_name='dispatch_stops' then
    if tg_op<>'UPDATE' or (to_jsonb(new)-array['notes','updated_at']) is distinct from (to_jsonb(old)-array['notes','updated_at']) then raise exception 'corrected_trip_history_immutable' using errcode='55000';end if;
   elsif tg_table_name in('dispatch_trip_loads','physical_journey_trips') or tg_op in('INSERT','DELETE') or old_id is distinct from new_id then
    raise exception 'corrected_trip_history_immutable' using errcode='55000';
   end if;
  end if;
 end loop;
 if tg_op='DELETE' then return old;end if;return new;
exception when lock_not_available then raise exception 'trip_correction_concurrent_change' using errcode='40001';
end;$function$
;

CREATE OR REPLACE FUNCTION finance_private.guard_open_complement_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare row_data jsonb;t uuid;expense uuid;a finance_private.expense_open_complement_amendments%rowtype;v jsonb;
begin
 if tg_table_name='expense_cost_regularizations' and tg_op='INSERT' then if exists(select 1 from finance_private.open_complement_extinctions x where x.tenant_id=new.tenant_id and x.expense_id=new.expense_id and x.regularization_id=new.id and x.request_id=new.request_id and x.actor_id=auth.uid() and new.actor_id=auth.uid() and new.proposal=x.proposal and new.payable_id=x.payable_id and new.charge_id=x.charge_id and new.before_cents::text=x.cost_before->>'effective_amount_cents' and new.after_cents::text=x.proposal->>'amount_cents' and new.ordinal=1 and new.previous_id is null) and finance_private.can_repair_unloading(new.tenant_id) then return new;end if;end if;
 for row_data in select x from jsonb_array_elements(case when tg_op='INSERT' then jsonb_build_array(to_jsonb(new)) when tg_op='DELETE' then jsonb_build_array(to_jsonb(old)) else jsonb_build_array(to_jsonb(old),to_jsonb(new)) end)x loop
  t:=(row_data->>'tenant_id')::uuid;expense:=null;
  if tg_table_name='payables' then select e.id into expense from public.finance_expense_items e where e.tenant_id=t and e.payable_id=(row_data->>'id')::uuid;
  elsif tg_table_name='finance_movement_voids' then select alloc.expense_id into expense from public.finance_expense_allocations alloc join finance_private.expense_open_complement_amendments j on j.tenant_id=alloc.tenant_id and j.expense_id=alloc.expense_id where alloc.tenant_id=t and alloc.movement_id=(row_data->>'movement_id')::uuid limit 1;
  else expense:=(row_data->>'expense_id')::uuid;end if;
  select * into a from finance_private.expense_open_complement_amendments x where x.tenant_id=t and x.expense_id=expense order by x.ordinal desc limit 1;
  if a.id is null then continue;end if;
  if not pg_try_advisory_xact_lock(hashtextextended(t::text||':finance',0)) then raise exception 'finance_open_complement_busy' using errcode='40001';end if;
  if tg_table_name='payables' and tg_op='UPDATE' then
   if exists(select 1 from finance_private.expense_cost_tickets k where k.transaction_id=txid_current() and k.tenant_id=t and k.payable_id=old.id and k.actor_id=auth.uid() and k.before_data=to_jsonb(old) and k.after_data=to_jsonb(new)) then continue;end if;
   if (to_jsonb(old)-array['status','updated_at','paid_amount','paid_at','bank_account_id','approved_at','approved_by']) is distinct from (to_jsonb(new)-array['status','updated_at','paid_amount','paid_at','bank_account_id','approved_at','approved_by']) or new.status not in('pending','approved','paid','partial') then raise exception 'finance_open_complement_source_protected' using errcode='55000';end if;
   v:=finance_private.expense_cost_effective(t,expense);
   if v->>'verified' is distinct from 'true' then raise exception 'finance_open_complement_chain_invalid' using errcode='55000';end if;
  else raise exception 'finance_open_complement_source_protected' using errcode='55000';end if;
 end loop;
 if tg_op='DELETE' then return old;end if;return new;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.guard_reported_payable_lifecycle()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare material_changed boolean;paid numeric;
begin
 material_changed:=tg_op='UPDATE' and (row(old.supplier_id,old.supplier_name,old.category,old.description,old.amount,old.due_date,old.document_number,old.notes)
   is distinct from row(new.supplier_id,new.supplier_name,new.category,new.description,new.amount,new.due_date,new.document_number,new.notes));
 if tg_op='INSERT' and new.status='paid' then raise exception 'finance_payable_payment_required' using errcode='23514';end if;
 if tg_op='UPDATE' and old.status='paid' and material_changed then raise exception 'finance_paid_payable_immutable' using errcode='55000';end if;
 if tg_op='UPDATE' and old.status='approved' and material_changed then new.status:='pending';new.approved_at:=null;new.approved_by:=null;end if;
 if tg_op='UPDATE' and new.status<>'approved' then new.approved_at:=null;new.approved_by:=null;end if;
 if tg_op='UPDATE' and new.status<>'paid' then new.paid_at:=null;end if;
 if new.status='paid' then
  select coalesce(sum(amount),0) into paid from public.payables_payments where tenant_id=new.tenant_id and payable_id=new.id;
  if paid<new.amount then raise exception 'finance_payable_payment_required' using errcode='23514';end if;
 end if;
 if tg_op='UPDATE' and new.status='cancelled' and old.status<>'cancelled' and exists(select 1 from public.payables_payments where tenant_id=new.tenant_id and payable_id=new.id) then
  raise exception 'finance_payable_reverse_payments_first' using errcode='55000';
 end if;
 return new;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.late_payment_composition_proved(_tenant uuid, _table text, _row jsonb, _depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare source jsonb;link record;m public.finance_movements%rowtype;amount numeric;day date;account uuid;matches integer:=0;identifier uuid;used numeric;
begin
 if _depth>3 then return false;end if;
 identifier:=(_row->>'id')::uuid;amount:=(_row->>'amount')::numeric*100;
 if not coalesce(amount>0 and amount=trunc(amount) and amount<=99999999999999,false) then return false;end if;
 account:=(_row->>'bank_account_id')::uuid;
 day:=case when _table in('load_payments','closing_report_payments') then (_row->>'payment_date')::date else (coalesce(_row->>'received_at',_row->>'paid_at',_row->>'posted_at')::timestamptz at time zone 'America/Sao_Paulo')::date end;
 if day is null or not isfinite(day) then return false;end if;
 if _table in('load_payments','closing_report_payments') then
  select to_jsonb(p) into source from public.receivables_payments p where p.tenant_id=_tenant and p.id=(case when _table='load_payments' then _row->>'receivable_payment_id' else _row->>'canonical_receivable_payment_id' end)::uuid;
  return source is not null and source->>'receivable_id' is not distinct from _row->>'receivable_id' and (source->>'amount')::numeric*100=amount and source->>'bank_account_id' is not distinct from _row->>'bank_account_id'
   and ((source->>'received_at')::timestamptz at time zone 'America/Sao_Paulo')::date=day and finance_private.late_payment_composition_proved(_tenant,'receivables_payments',source,_depth+1);
 elsif _table='bank_transactions' then
  for link in select l.* from public.finance_receivable_movement_links l where l.tenant_id=_tenant and l.bank_transaction_id=identifier and l.action='receive' loop
   select to_jsonb(p) into source from public.receivables_payments p where p.tenant_id=_tenant and p.id=link.payment_id and p.financial_command_id=link.command_id and p.bank_transaction_id=identifier;
   if source is not null and _row->>'transaction_type'='credit' and (source->>'amount')::numeric*100=amount and source->>'bank_account_id'=_row->>'bank_account_id'
    and ((source->>'received_at')::timestamptz at time zone 'America/Sao_Paulo')::date=day and finance_private.late_payment_composition_proved(_tenant,'receivables_payments',source,_depth+1) then matches:=matches+1;end if;
  end loop;return matches=1;
 elsif _table='receivables_payments' then
  if exists(select 1 from public.finance_receipt_allocation_corrections c where c.tenant_id=_tenant and c.payment_id=identifier) then return false;end if;
  for link in select l.* from public.finance_receivable_movement_links l where l.tenant_id=_tenant and l.payment_id=identifier and l.action='receive' and l.command_id=(_row->>'financial_command_id')::uuid and l.bank_transaction_id=(_row->>'bank_transaction_id')::uuid loop
   select * into m from public.finance_movements where tenant_id=_tenant and id=link.movement_id;
   if found and m.direction='in' and m.bank_account_id=account and m.occurred_on=day and finance_private.frozen_movement(_tenant,m.id) then
    used:=finance_private.receipt_movement_used_cents(_tenant,m.id);
    if used>=amount and used<=m.amount_cents then matches:=matches+1;end if;
   end if;
  end loop;return matches=1;
 elsif _table='payables_payments' then
  if _row->>'bank_transaction_id' is not null then return false;end if;
  for link in select l.* from public.finance_payable_movement_links l where l.tenant_id=_tenant and l.payment_id=identifier and l.payable_id=(_row->>'payable_id')::uuid and l.origin='canonical' and l.amount_cents=amount and not exists(select 1 from public.finance_payable_link_reversals r where r.tenant_id=_tenant and r.link_id=l.id) loop
   select * into m from public.finance_movements where tenant_id=_tenant and id=link.movement_id;
   if found and m.direction='out' and m.bank_account_id=account and m.occurred_on=day and finance_private.frozen_movement(_tenant,m.id) then
    used:=finance_private.movement_used_cents(_tenant,m.id);if used>=amount and used<=m.amount_cents then matches:=matches+1;end if;
   end if;
  end loop;return matches=1;
 elsif _table='driver_settlement_payments' then
  for link in select l.* from public.finance_settlement_movement_links l where l.tenant_id=_tenant and l.payment_id=identifier and l.settlement_id=(_row->>'settlement_id')::uuid and l.amount_cents=amount and not exists(select 1 from public.finance_settlement_link_reversals r where r.tenant_id=_tenant and r.link_id=l.id) loop
   select * into m from public.finance_movements where tenant_id=_tenant and id=link.movement_id;
   if found and m.direction='out' and m.occurred_on=day and finance_private.frozen_movement(_tenant,m.id) then
    used:=finance_private.movement_used_cents(_tenant,m.id);if used>=amount and used<=m.amount_cents then matches:=matches+1;end if;
   end if;
  end loop;return matches=1;
 end if;
 return false;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.lock_active_movement_use(_tenant uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
 if not pg_try_advisory_xact_lock(hashtextextended(_tenant::text||':finance',0)) then raise exception 'finance_movement_use_busy' using errcode='40001';end if;
 if not finance_private.can_access(_tenant) then raise exception 'finance_access_denied' using errcode='42501';end if;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.assert_active_movement_reference(_tenant uuid, _movement uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$begin
 perform finance_private.lock_active_movement_use(_tenant);
 if not exists(select 1 from public.finance_movements where tenant_id=_tenant and id=_movement) then raise exception 'finance_movement_reference_invalid' using errcode='23514';end if;
 if not finance_private.movement_is_active(_tenant,_movement) then raise exception 'finance_movement_voided' using errcode='23514';end if;
end$function$
;

CREATE OR REPLACE FUNCTION finance_private.legacy_payable_payment_issue(_tenant uuid, _payment uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p public.payables_payments%rowtype;title public.payables%rowtype;tx public.bank_transactions%rowtype;begin
 select * into p from public.payables_payments where tenant_id=_tenant and id=_payment;
 if not found then return 'finance_legacy_payment_not_found';end if;
 select * into title from public.payables where tenant_id=_tenant and id=p.payable_id;
 if not found then return 'finance_legacy_payable_not_found';end if;
 if p.amount is null or p.amount::text in('NaN','Infinity','-Infinity') or p.amount<=0 or p.amount*100<>trunc(p.amount*100) or p.amount*100>99999999999999 then return 'finance_legacy_payment_amount_invalid';end if;
 if p.paid_at is null or not isfinite(p.paid_at) then return 'finance_legacy_payment_date_invalid';end if;
 if not exists(select 1 from public.bank_accounts where tenant_id=_tenant and id=p.bank_account_id) then return 'finance_legacy_payment_account_invalid';end if;
 if exists(select 1 from public.finance_payable_movement_links where tenant_id=_tenant and payment_id=p.id and origin='canonical') then return 'finance_legacy_payment_not_eligible';end if;
 if exists(select 1 from public.finance_payable_movement_links l where l.tenant_id=_tenant and l.payment_id=p.id and not exists(select 1 from public.finance_payable_link_reversals r where r.tenant_id=_tenant and r.link_id=l.id)) then return 'finance_legacy_payment_already_associated';end if;
 if p.bank_transaction_id is not null then
  select * into tx from public.bank_transactions where tenant_id=_tenant and id=p.bank_transaction_id;
  if not found or tx.bank_account_id is distinct from p.bank_account_id or tx.transaction_type is distinct from 'debit'
   or tx.amount is distinct from p.amount or tx.posted_at is null or not isfinite(tx.posted_at)
   or (tx.posted_at at time zone 'America/Sao_Paulo')::date<>(p.paid_at at time zone 'America/Sao_Paulo')::date then return 'finance_legacy_bank_source_mismatch';end if;
  if exists(select 1 from public.payables_payments other where other.tenant_id=_tenant and other.bank_transaction_id=tx.id and other.id<>p.id)
   or exists(select 1 from public.receivables_payments other where other.tenant_id=_tenant and other.bank_transaction_id=tx.id)
   or exists(select 1 from public.receivable_payment_reversals other where other.tenant_id=_tenant and other.bank_transaction_id=tx.id)
   or exists(select 1 from public.load_payments other where other.tenant_id=_tenant and other.bank_transaction_id=tx.id)
   or exists(select 1 from public.finance_receivable_movement_links other where other.tenant_id=_tenant and other.bank_transaction_id=tx.id) then return 'finance_legacy_bank_source_ambiguous';end if;
 end if;
 return null;
end$function$
;

CREATE OR REPLACE FUNCTION public.sync_employee_advance_from_payable()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'paid' THEN
      UPDATE public.employee_advances
         SET status = 'paid', paid_at = COALESCE(NEW.paid_at, now()), updated_at = now()
       WHERE payable_id = NEW.id AND status <> 'paid';
    ELSIF NEW.status = 'cancelled' THEN
      UPDATE public.employee_advances
         SET status = 'cancelled', updated_at = now()
       WHERE payable_id = NEW.id AND status <> 'cancelled';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public._recalc_payable_paid()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_payable_id UUID;
  v_total NUMERIC;
  v_amount NUMERIC;
  v_status TEXT;
BEGIN
  v_payable_id := COALESCE(NEW.payable_id, OLD.payable_id);
  SELECT COALESCE(SUM(amount),0) INTO v_total FROM finance_private.active_payable_payments WHERE payable_id = v_payable_id;
  SELECT amount, status INTO v_amount, v_status FROM public.payables WHERE id = v_payable_id;
  IF v_status = 'cancelled' THEN
    UPDATE public.payables SET paid_amount = v_total, updated_at = now() WHERE id = v_payable_id;
    RETURN COALESCE(NEW, OLD);
  END IF;
  UPDATE public.payables SET
    paid_amount = v_total,
    status = CASE
      WHEN v_total <= 0 THEN CASE WHEN v_status IN ('paid','partial') THEN 'approved' ELSE v_status END
      WHEN v_total >= v_amount THEN 'paid'
      ELSE 'partial'
    END,
    paid_at = CASE WHEN v_total >= v_amount THEN COALESCE(paid_at, now()) ELSE NULL END,
    updated_at = now()
  WHERE id = v_payable_id;
  RETURN COALESCE(NEW, OLD);
END $function$
;
